class Tokenizer:
    """Basit bir tokenizer: sayıları, isimleri, işleçleri ve parantezleri token'lere ayırır."""
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)
        self.tokens = []

    def current_char(self):
        if self.pos < self.length:
            return self.text[self.pos]
        return None

    def peek_char(self):
        if self.pos + 1 < self.length:
            return self.text[self.pos + 1]
        return None

    def advance(self):
        self.pos += 1

    def skip_whitespace(self):
        while self.current_char() and self.current_char() in ' \t\r':
            self.advance()

    def skip_comment(self):
        if self.current_char() == '#':
            while self.current_char() and self.current_char() != '\n':
                self.advance()

    def read_number(self):
        start = self.pos
        has_dot = False
        while self.current_char() and (self.current_char().isdigit() or self.current_char() == '.'):
            if self.current_char() == '.':
                if has_dot:
                    break
                has_dot = True
            self.advance()
        num_str = self.text[start:self.pos]
        if has_dot:
            return ('NUMBER', float(num_str))
        return ('NUMBER', int(num_str))

    def read_identifier(self):
        start = self.pos
        while self.current_char() and (self.current_char().isalnum() or self.current_char() == '_'):
            self.advance()
        return ('IDENTIFIER', self.text[start:self.pos])

    def tokenize(self):
        while self.pos < self.length:
            self.skip_whitespace()
            self.skip_comment()

            ch = self.current_char()
            if ch is None:
                break

            # Satır sonu veya noktalı virgül
            if ch == '\n' or ch == ';':
                self.tokens.append(('SEP', ch))
                self.advance()
                continue

            # Parantezler
            if ch == '(':
                self.tokens.append(('LPAREN', ch))
                self.advance()
                continue
            if ch == ')':
                self.tokens.append(('RPAREN', ch))
                self.advance()
                continue

            # Virgül
            if ch == ',':
                self.tokens.append(('COMMA', ch))
                self.advance()
                continue

            # Atama
            if ch == '=':
                self.tokens.append(('ASSIGN', ch))
                self.advance()
                continue

            # İşleçler: ** kontrolü önce
            if ch == '*' and self.peek_char() == '*':
                self.tokens.append(('POWER', '**'))
                self.advance()
                self.advance()
                continue

            # Tek karakterli işleçler
            if ch in '+-*/%':
                self.tokens.append(('OP', ch))
                self.advance()
                continue

            # Sayı
            if ch.isdigit() or (ch == '.' and self.peek_char() and self.peek_char().isdigit()):
                self.tokens.append(self.read_number())
                continue

            # İsim (değişken/fonksiyon)
            if ch.isalpha() or ch == '_':
                self.tokens.append(self.read_identifier())
                continue

            # Bilinmeyen karakter
            raise SyntaxError(f'Geçersiz karakter: {ch}')

        self.tokens.append(('EOF', None))
        return self.tokens


